import os
from web3 import Web3
from dotenv import load_dotenv
load_dotenv()
# 1. Credentials & Configuration
AMOY_RPC = os.getenv("AMOY_RPC")
PRIVATE_KEY = os.getenv("PRIVATE_KEY")

# 2. Contract ABI & Bytecode
ABI = [
    {
        "inputs": [{"internalType": "string", "name": "_ipfsCID", "type": "string"}],
        "name": "anchorEvidence",
        "outputs": [],
        "stateMutability": "nonpayable",
        "type": "function"
    }
]

# Paste the Bytecode you copied from Remix inside the quotes below:
BYTECODE = ""

# 3. Connect and Build Deployment Transaction
w3 = Web3(Web3.HTTPProvider(AMOY_RPC))
account = w3.eth.account.from_key(PRIVATE_KEY)

print(f"Deploying contract from address: {account.address}")

CipherLedger = w3.eth.contract(abi=ABI, bytecode=BYTECODE)
nonce = w3.eth.get_transaction_count(account.address)

txn = CipherLedger.constructor().build_transaction({
    'chainId': 80002,
    'gas': 500000,                                    # Reduced gas limit to fit wallet balance
    'maxFeePerGas': w3.to_wei('60', 'gwei'),          # Covers base fee requirement
    'maxPriorityFeePerGas': w3.to_wei('30', 'gwei'),  # Passes the 25 Gwei minimum priority tip
    'nonce': nonce,
})

# 4. Sign & Broadcast
signed_txn = w3.eth.account.sign_transaction(txn, private_key=PRIVATE_KEY)
tx_hash = w3.eth.send_raw_transaction(signed_txn.raw_transaction)

print(f"Deployment Broadcasted! Tx Hash: {tx_hash.hex()}")
print("Waiting for block confirmation...")

receipt = w3.eth.wait_for_transaction_receipt(tx_hash)
print("\n" + "="*50)
print(f"SUCCESS! New Contract Address: {receipt.contractAddress}")
print("="*50)